/**
 * Money reads vs the CLIENT: the headline, the equation figures and the
 * per-person breakdown for every scenario in balancesParityCases.json (values
 * generated by running explainMoneyPosition / computePairwiseBreakdown).
 */
import { assert, assertEquals, assertStringIncludes } from 'jsr:@std/assert@1'
import parityCases from '../../../_shared/money/balancesParityCases.json' with { type: 'json' }
import { computeMoney, computeMyMoneyLine, getBalancesTool, getMyMoneyTool, mergeSettlements, myMoneyHeadline, pairwiseBreakdown } from './money.ts'
import { baseDb, IDS, makeCtx, text } from './testing.ts'
import type { SnapshotData } from '../../../_shared/todos/snapshot.ts'

// deno-lint-ignore no-explicit-any
type Any = any

for (const s of parityCases.scenarios as Any[]) {
  for (const v of s.expected.viewers as Any[]) {
    Deno.test(`my money headline matches the client: ${s.name} (${v.viewer})`, () => {
      const data = { trip: { base_currency: s.base }, participants: s.roster.map((id: string) => ({ user_id: id })), expenses: s.expenses, settlements: s.settlements, carryovers: s.carryovers } as unknown as SnapshotData
      const m = computeMoney(data)
      const roster = Object.entries(parityCases.names).map(([userId, name]) => ({ userId, name, role: null, active: true, confirmationStatus: null }))
      const h = myMoneyHeadline(m, { userId: v.viewer, roster })
      assertEquals({ kind: h.kind, amount: h.amount, text: h.text, note: h.note }, v.headline)
      assertEquals(h.paid, v.paid)
      assertEquals(h.share, v.share)
      assertEquals(h.sentConfirmed, v.sentConfirmed)
      assertEquals(h.receivedConfirmed, v.receivedConfirmed)
      assertEquals(h.sentWaiting, v.sentWaiting)
      assertEquals(h.receivedWaiting, v.receivedWaiting)
      assertEquals(pairwiseBreakdown(data.expenses, mergeSettlements(data, m), m.ledgerIds, v.viewer, s.base), v.pairwise)
    })
  }
}

Deno.test("get_my_money on the fixture trip: Tim's marked-paid 5.00 is not in the balance and is described as waiting", async () => {
  const ctx = makeCtx(baseDb(), 'tim')
  const r = await getMyMoneyTool.run({}, ctx)
  const c = r.content as Any
  assert(c.payments.some((p: Any) => p.state.startsWith('Sent, waiting')))
  assert(c.payments.some((p: Any) => p.state.startsWith('Suggested')))
  const line = await computeMyMoneyLine(makeCtx(baseDb(), 'sam'))
  assert(line && line.length > 0)
})

Deno.test('get_balances is the Settle up view: sums to zero, names not ids, unclaimed receipt listed', async () => {
  const ctx = makeCtx(baseDb(), 'sam')
  const r = await getBalancesTool.run({}, ctx)
  const c = r.content as Any
  assertEquals(c.balances.length, 4)
  assert(c.balances.every((b: Any) => typeof b.person === 'string' && b.person.length > 0))
  assert(!text(c).includes(IDS.sam), 'no user ids in money output')
  assertEquals(c.unclaimed_receipts.length, 1)
  assertStringIncludes(c.unclaimed_receipts[0].receipt, '<trip_data')
})

Deno.test('money tools return a plain message, not a crash, when the trip cannot be read', async () => {
  const db = baseDb()
  db.errors = { expenses: { code: 'XX000', message: 'boom' } }
  const r = await getMyMoneyTool.run({}, makeCtx(db, 'sam'))
  assertEquals(r.is_error, true)
  assertStringIncludes(JSON.stringify(r.content), 'try again')
  assertEquals(await computeMyMoneyLine(makeCtx(db, 'sam')), null)
})
